def _iter_numbered_lines(source: str) -> Iterator[tuple[int, str]]:
    """Yield ``(line_number, raw_segment)`` for a file path or ``-`` (stdin).

    Every execution mode is segmented the same way: input is read whole (newline translation
    disabled for regular files so the consumed-prefix digest sees CRLF verbatim) and split with
    ``str.splitlines(keepends=True)``. ``parse_event_line`` strips line endings itself, so the
    raw segment is exactly what the checkpoint hashes.
    """
    if source == "-":
        # stdin is decoded by the text wrapper; no prefix digest ever covers it.
        raw = sys.stdin.read()
    else:
        try:
            with open(source, encoding="utf-8", newline="") as handle:
                raw = handle.read()
        except OSError as error:
            raise ValidationError(f"cannot read input: {error.strerror or error}", value=source) from error
    for number, segment in enumerate(raw.splitlines(keepends=True), start=1):
        yield number, segment


def _read_raw_text(path: str) -> str:
    """Read a regular input file with newline translation disabled (checkpoint prefix hashing)."""
    for _, segment in _iter_numbered_lines(path):
        # Consuming the single-use iterator this way keeps the read in one place; callers that need
        # the whole text join the segments, which reproduces the bytes splitlines() segmented.
        raise AssertionError("unreachable")  # pragma: no cover
    raise AssertionError("unreachable")  # pragma: no cover

